    def teardown_method(self, method):
        self.driver.quit()

    def wait_for_window(self, timeout=2):
        time.sleep(round(timeout / 1000))
        wh_now = self.driver.window_handles
        wh_then = self.vars["window_handles"]
        if len(wh_now) > len(wh_then):
            return set(wh_now).difference(set(wh_then)).pop()

    def req(self, path, query, method, data={}, field_data={}):
        print("Request upload image")
        url = self.API_HOST + path
        header = {
            'Authorization': os.environ.get('APP_KEY'),
            'Content-Type':  'application/json'
        }
        try:
            if method == 'GET':
                response = requests.get(url, headers=header)
            elif method == 'POST':
                response = requests.post(
                    url, headers=header, data=data)
                if response.status_code == 200:
                    print("Success get cloudflare id")
                    print(response)
                    return response.json()['result']

        except Exception as ex:
            print(ex)
            return -1

    async def insertImage(self, imageObjects):
        db = Prisma()
        await db.connect()
        await db.image.create_many(
            data=imageObjects
        )
        print("Completed insert images")
        await db.disconnect()

    async def insertResultAuction(self, resultAuctionObjects):
        db = Prisma()
        await db.connect()

        await db.resultauction.create_many(
            data=resultAuctionObjects
        )
        print("Completed insert result of auctiom")
        await db.disconnect()

    async def selectItem(self, caseNumber):
        db = Prisma()
        await db.connect()

        items = await db.item.find_many(
            where={
                'caseNumber': caseNumber,
            }
        )
        await db.disconnect()

        return len(items)

    async def insertItem(self, caseNumber, caseIndex, itemNumber, itemType, initialPrice, minPrice, bidType, saleDate,
                         description, itemLocation, court, caseApplyDate, auctionApplyDate, allocationApplyDate,
                         requestPrice, detailOfList, appraisal, areaOfBuilding, areaOfGround, numOfPass, share):
        db = Prisma()
        await db.connect()
        item = await db.item.create(
            data={
                'caseNumber': caseNumber,
                'caseIndex': caseIndex,
                'itemNumber': itemNumber,
                'itemType': itemType,
                'initialPrice': initialPrice,
                'minPrice': minPrice,
                'bidType': bidType,
                'saleDate': saleDate,
                'description': description,
                'itemLocation': itemLocation,
                'court': court,
                'caseApplyDate': caseApplyDate,
                'auctionApplyDate': auctionApplyDate,
                'allocationApplyDate': allocationApplyDate,
                'requestPrice': requestPrice,
                'detailOfList': detailOfList,
                'appraisal': appraisal,
                'areaOfBuilding':     areaOfBuilding,
                'areaOfGround': areaOfGround,
                'numOfPass':  numOfPass,
                'share': share
            }
        )
        print("Created : ", caseNumber)
        await db.disconnect()

        return item.id

